import{_ as a,a as t}from"./chunks/Fixpipe_Channel_Split_with_dirty.CvIcEDCh.js";import{_ as l,o as i,a as p,b as _}from"./app.UgfkfLuP.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API<a npu_parse_enabled=\\"true\\"></a>","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"矩阵计算搬运","link":"/api/SIMD-API/c_api/cube_datamove/cube_datamove"},{"text":"矩阵搬出关键特性说明","link":"/api/SIMD-API/c_api/cube_datamove/cube_store_key_features/cube_store_key_features"},{"text":"F32 Channel Split","link":"/api/SIMD-API/c_api/cube_datamove/cube_store_key_features/F32-Channel-Split"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/cube_datamove/cube_store_key_features/F32-Channel-Split.md","filePath":"api/SIMD-API/c_api/cube_datamove/cube_store_key_features/F32-Channel-Split.md","outlineHeaders":[{"level":2,"title":"特性说明","slug":"特性说明","link":"#特性说明"},{"level":2,"title":"特性约束","slug":"特性约束","link":"#特性约束"},{"level":2,"title":"使用示例","slug":"使用示例","link":"#使用示例"}],"lastUpdated":1791622466000}'),n={name:"api/SIMD-API/c_api/cube_datamove/cube_store_key_features/F32-Channel-Split.md"};function r(c,e,s,o,d,h){return i(),p("div",null,[...e[0]||(e[0]=[_('<div><article class="markdown-body"><h1>F32 Channel Split</h1><h2 id="特性说明">特性说明<a class="header-anchor" href="#特性说明">​</a></h2><p>矩阵计算的搬出过程中对于目标类型为f32，如果开启了Channel Split（通道拆分），硬件就能够将16×16的分形矩阵转换为16×8的小z分形矩阵，此时每个16×16的分形矩阵将被拆分为2个独立的16×8的小z分形矩阵。</p><div data-filter="A3,910b"><p>Atlas A3系列产品和Atlas A2系列产品在<a href="../cube_compute_store/asc_copy_l0c2gm_arch_2201.html">asc_copy_l0c2gm（Atlas A3系列产品和Atlas A2系列产品）</a>中设置<code>channel_split=true</code>。使用时同时满足下文对输出格式和<a href="../../cube_compute/mmad_compute_key_features/UnitFlag.html">UnitFlag</a>的限制；格式转换的区别见<a href="NZ2ND.html">NZ2ND</a>。</p></div><div data-filter="950"><p>Ascend 950PR&amp;950DT系列产品在<a href="../cube_compute_store/asc_copy_l0c2gm_arch_3510.html">asc_copy_l0c2gm（Ascend 950PR&amp;950DT系列产品）</a>中设置<code>enable_channel_split=true</code>。使用时同时满足下文对输出格式和<a href="../../cube_compute/mmad_compute_key_features/UnitFlag.html">UnitFlag</a>的限制；格式转换的区别见<a href="NZ2ND.html">NZ2ND</a>和<a href="NZ2DN.html">NZ2DN</a>。</p></div><h2 id="特性约束">特性约束<a class="header-anchor" href="#特性约束">​</a></h2><div data-filter="A3,910b"><ul><li><p>针对如下产品型号：</p><div data-filter="A3"><p>Atlas A3系列产品</p></div><div data-filter="910b"><p>Atlas A2系列产品</p></div><p>当Fixpipe指令的输入和输出数据类型都为float，Nz输出到GM，并且不开启Nz2ND与unitFlag时，才能够开启Channel Split功能。</p></li></ul></div><div data-filter="950"><ul><li>针对Ascend 950PR&amp;950DT系列产品，当Fixpipe指令的输入和输出数据类型都为float,Nz输出到GM，并且不开启Nz2ND、Nz2DN与unitFlag时，才能够开启Channel Split功能。当前搬出到L1 Buffer和Unified Buffer（UB）不支持该功能。</li></ul></div><h2 id="使用示例">使用示例<a class="header-anchor" href="#使用示例">​</a></h2><p>如下图所示，当开启Channel Split功能后，shape为[64,32]的源操作数将会被拆分为16个独立的16x8分形矩阵。</p><p><strong>图1</strong> F32 Channel Split示意图（无无效数据）</p><p><img src="'+a+'" alt></p><p>当开启Channel Split功能后，n_size（源Nz矩阵在N方向上的大小）必须为8的倍数。如下图所示，shape为[64,24]的源操作数将会被拆分为3列16x8分形矩阵。</p><p><strong>图2</strong> F32 Channel Split示意图（有无效数据）</p><p><img src="'+t+'" alt></p></article></div>',1)])])}const A=l(n,[["render",r]]);export{f as __pageData,A as default};
